CREATE TABLE product_units(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(50) NOT NULL,factor DECIMAL(19,6) NOT NULL,version BIGINT NOT NULL DEFAULT 1,is_base BOOLEAN NOT NULL DEFAULT 0,warehouse_id BIGINT UNSIGNED NULL,base_marker TINYINT GENERATED ALWAYS AS (IF(is_base,1,NULL)) STORED,UNIQUE(product_id,name),UNIQUE(product_id,base_marker),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CHECK(factor>0),CHECK((is_base=1 AND factor=1 AND warehouse_id IS NULL) OR (is_base=0 AND warehouse_id IS NOT NULL)));
INSERT INTO product_units(product_id,name,factor,is_base) SELECT id,base_unit,1,1 FROM products;
CREATE TABLE conversion_snapshots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_id VARCHAR(100) NOT NULL,unit_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,unit_name VARCHAR(50) NOT NULL,factor DECIMAL(19,6) NOT NULL,unit_version BIGINT NOT NULL,quantity DECIMAL(19,6) NOT NULL,base_quantity DECIMAL(38,12) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(unit_id) REFERENCES product_units(id),FOREIGN KEY(product_id) REFERENCES products(id));
